function [MRSCont] = OspreyFit(MRSCont)
%% [MRSCont] = OspreyFit(MRSCont)
%   This function performs spectral fitting on MRS data loaded previously
%   using OspreyLoad.
%
%   The method of fit, fitting range, included metabolites and other
%   settings are set in the job file.
%
%   USAGE:
%       MRSCont = OspreyFit(MRSCont);
%
%   INPUTS:
%       MRSCont     = Osprey MRS data container.
%
%   OUTPUTS:
%       MRSCont     = Osprey MRS data container.
%
%   AUTHOR:
%       Dr. Georg Oeltzschner (Johns Hopkins University, 2019-02-24)
%       goeltzs1@jhmi.edu
%
%   CREDITS:
%       This code is based on numerous functions from the FID-A toolbox by
%       Dr. Jamie Near (McGill University)
%       https://github.com/CIC-methods/FID-A
%       Simpson et al., Magn Reson Med 77:23-33 (2017)
%
%   HISTORY:
%       2019-02-24: First version of the code.

outputFolder = MRSCont.outputFolder;
diary(fullfile(outputFolder, 'LogFile.txt'));

if MRSCont.flags.isGUI
    progressText = MRSCont.flags.inProgress;
else
    progressText = '';
end

% ----- Load fit settings and fit the metabolite data -----
% Checking for version, toolbox, and previously run modules
[~,MRSCont.ver.CheckOsp ] = osp_CheckRunPreviousModule(MRSCont, 'OspreyFit');
% Start timer
MRSCont.runtime.Fit = 0;

% Initialise the fit - this step includes:
% - Parse the correct basis set
% - Apply settings on which metabolites/MM/lipids to include in the fit
% - Check for inconsistencies between basis set and data
[MRSCont] = osp_fitInitialise(MRSCont);
%MRSCont.opts.fit.outputFolder = outputFolder;

% Call the fit functions (depending on sequence type)
if ~MRSCont.flags.isPRIAM && ~MRSCont.flags.isMRSI
    if MRSCont.flags.isUnEdited
        [MRSCont] = osp_fitUnEdited(MRSCont);
    elseif MRSCont.flags.isMEGA
        [MRSCont] = osp_fitMEGA(MRSCont);
    elseif MRSCont.flags.isHERMES
        [MRSCont] = osp_fitHERMES(MRSCont);
    elseif MRSCont.flags.isHERCULES
        % For now, fit HERCULES like HERMES data
        [MRSCont] = osp_fitHERCULES(MRSCont);
    else
        msg = 'No flag set for sequence type!';
        fprintf(msg);
        error(msg);
    end
else
    [MRSCont] = osp_fitMultiVoxel(MRSCont);
end


% ----- Perform water reference and short-TE water fit -----
% The water signal is automatically integrated when the LCModel fit option is
% being used. In Osprey, we explicitly model the water data with a
% dedicated simulated water basis function.
if strcmpi(MRSCont.opts.fit.method, 'Osprey')

    % If water reference exists, fit it
    if MRSCont.flags.hasRef
        refFitTime = tic;
        % Loop over all the datasets here
        for kk = 1:MRSCont.nDatasets
            [~] = printLog('OspreyFitRef',kk,1,MRSCont.nDatasets,progressText,MRSCont.flags.isGUI ,MRSCont.flags.isMRSI);
            if ~(MRSCont.flags.didFit == 1 && MRSCont.flags.speedUp && isfield(MRSCont, 'fit') && (kk > length(MRSCont.fit.results.ref.fitParams))) || ~strcmp(MRSCont.ver.Osp,MRSCont.ver.CheckOsp)
                [MRSCont] = osp_fitWater(MRSCont, kk, 'ref');
            end
        end
        time = toc(refFitTime);
        if MRSCont.flags.isGUI
            set(progressText,'String' ,sprintf('... done.\n Elapsed time %f seconds',time));
            pause(1);
        end
        fprintf('... done.\n Elapsed time %f seconds\n',time);
        MRSCont.runtime.FitRef = time;
        MRSCont.runtime.Fit = MRSCont.runtime.Fit + time;
    end

    % If short TE water reference exists, fit it
    if MRSCont.flags.hasWater
        waterFitTime = tic;
        % Loop over all the datasets here
        for kk = 1:MRSCont.nDatasets
            [~] = printLog('OspreyFitWater',kk,1,MRSCont.nDatasets,progressText,MRSCont.flags.isGUI ,MRSCont.flags.isMRSI);
            if ~(MRSCont.flags.didFit == 1 && MRSCont.flags.speedUp && isfield(MRSCont, 'fit') && (kk > length(MRSCont.fit.results.w.fitParams))) || ~strcmp(MRSCont.ver.Osp,MRSCont.ver.CheckOsp)
                [MRSCont] = osp_fitWater(MRSCont, kk, 'w');
            end
        end
        time = toc(waterFitTime);
        fprintf('... done.\n Elapsed time %f seconds\n',time);
        MRSCont.runtime.FitWater = time;
        MRSCont.runtime.Fit = MRSCont.runtime.Fit + time;
    end

    MRSCont.runtime.Fit = MRSCont.runtime.Fit + MRSCont.runtime.FitMet;

else
    MRSCont.runtime.Fit =  MRSCont.runtime.FitMet;
end
[~] = printLog('Fulldone',MRSCont.runtime.Fit,MRSCont.nDatasets,progressText,MRSCont.flags.isGUI ,MRSCont.flags.isMRSI);


%% If DualVoxel or MRSI we want to extract y-axis scaling
if MRSCont.flags.isPRIAM || MRSCont.flags.isMRSI
    MRSCont = osp_scale_yaxis(MRSCont,'OspreyLoad');
    MRSCont.fit.resBasisSet = MRSCont.fit.resBasisSet{2,2};
end

%% Delete redundant resBasiset entries
if strcmpi(MRSCont.opts.fit.method, 'Osprey')
    if ~(MRSCont.flags.isPRIAM || MRSCont.flags.isMRSI)
        FitNames = fieldnames(MRSCont.fit.resBasisSet);
        NoFit = length(fieldnames(MRSCont.fit.resBasisSet));
        for sf = 1 : NoFit
            if iscell(MRSCont.fit.resBasisSet.(FitNames{sf}))
                MRSCont.fit.resBasisSet.(FitNames{sf}) = MRSCont.fit.resBasisSet.(FitNames{sf})(:,MRSCont.info.metab.unique_ndatapoint_spectralwidth_ind,:);
                for combs = 1 : length(MRSCont.info.metab.unique_ndatapoint_spectralwidth_ind)
                    resBasisSetNew.(FitNames{sf}).([MRSCont.info.metab.unique_ndatapoint_spectralwidth{combs}]) = MRSCont.fit.resBasisSet.(FitNames{sf})(:,combs,:);
                end
            else
                MRSCont.fit.resBasisSet.(FitNames{sf}).water = MRSCont.fit.resBasisSet.(FitNames{sf}).water(MRSCont.info.(FitNames{sf}).unique_ndatapoint_spectralwidth_ind);
                for combs = 1 : length(MRSCont.info.(FitNames{sf}).unique_ndatapoint_spectralwidth_ind)
                    resBasisSetNew.(FitNames{sf}).water.([MRSCont.info.(FitNames{sf}).unique_ndatapoint_spectralwidth{combs}]) = MRSCont.fit.resBasisSet.(FitNames{sf}).water{combs};
                end
            end
        end
        MRSCont.fit.resBasisSet = resBasisSetNew;
    end
end

%% Store  and print some QM parameters
if ~MRSCont.flags.isPRIAM && ~MRSCont.flags.isMRSI
    [MRSCont] = osp_fit_Quality(MRSCont);

    L = length(MRSCont.QM.tables.Properties.VariableNames);
    % Store data quality measures in csv file
    if MRSCont.flags.isUnEdited
        relResA = MRSCont.QM.relAmpl.metab_A';
        MRSCont.QM.tables.relResA = relResA;
    elseif MRSCont.flags.isMEGA
        if strcmp( MRSCont.opts.fit.style, 'Separate')
            relResA = MRSCont.QM.relAmpl.metab_A';
            relResdiff1 = MRSCont.QM.relAmpl.metab_diff1';
            MRSCont.QM.tables.relResA = relResA;
            MRSCont.QM.tables.relResdiff1 = relResdiff1;
        else
            relRessum = MRSCont.QM.relAmpl.metab_sum';
            relResdiff1 = MRSCont.QM.relAmpl.metab_diff1';
            MRSCont.QM.tables.relRessum = relRessum;
            MRSCont.QM.tables.relResdiff1 = relResdiff1;
        end
    elseif MRSCont.flags.isHERMES
            relRessum = MRSCont.QM.relAmpl.metab_sum';
            relResdiff1 = MRSCont.QM.relAmpl.metab_diff1';
            relResdiff2 = MRSCont.QM.relAmpl.metab_diff2';
            MRSCont.QM.tables.relRessum = relRessum;
            MRSCont.QM.tables.relResdiff1 = relResdiff1;
            MRSCont.QM.tables.relResdiff2 = relResdiff2;
    elseif MRSCont.flags.isHERCULES
        % For now, process HERCULES like HERMES data
            relRessum = MRSCont.QM.relAmpl.metab_sum';
            relResdiff1 = MRSCont.QM.relAmpl.metab_diff1';
            relResdiff2 = MRSCont.QM.relAmpl.metab_diff2';
            MRSCont.QM.tables.relRessum = relRessum;
            MRSCont.QM.tables.relResdiff1 = relResdiff1;
            MRSCont.QM.tables.relResdiff2 = relResdiff2;
    else
        msg = 'No flag set for sequence type!';
        fprintf(msg);
        error(msg);
    end

    % Loop over field names to populate descriptive fields of table for JSON export
    for JJ = L:length(MRSCont.QM.tables.Properties.VariableNames)
        switch MRSCont.QM.tables.Properties.VariableNames{JJ}
            case 'relResA'
                MRSCont.QM.tables.Properties.CustomProperties.VariableLongNames{'relResA'} = 'relResA';%CWDJ??
                MRSCont.QM.tables.Properties.VariableDescriptions{'relResA'} = 'Fit quality number for spectrum A relative amplitude of the residual compared to the standard deveiation of the noise';
                MRSCont.QM.tables.Properties.VariableUnits{'relResA'} = 'arbitrary';
            case 'relRessum'
                MRSCont.QM.tables.Properties.CustomProperties.VariableLongNames{'relRessum'} = 'relRessum';
                MRSCont.QM.tables.Properties.VariableDescriptions{'relRessum'} = 'Fit quality number for sum spectrum relative amplitude of the residual compared to the standard deveiation of the noise';
                MRSCont.QM.tables.Properties.VariableUnits{'relRessum'} = 'arbitrary';
            case 'relResdiff1'
                MRSCont.QM.tables.Properties.CustomProperties.VariableLongNames{'relResdiff1'} = 'relResdiff1';
                MRSCont.QM.tables.Properties.VariableDescriptions{'relResdiff1'} = 'Fit quality number for diff1 spectrum relative amplitude of the residual compared to the standard deveiation of the noise';
                MRSCont.QM.tables.Properties.VariableUnits{'relResdiff1'} = 'arbitrary';
            case 'relResdiff2'
                MRSCont.QM.tables.Properties.CustomProperties.VariableLongNames{'relResdiff2'} = 'relResdiff2';
                MRSCont.QM.tables.Properties.VariableDescriptions{'relResdiff2'} = 'Fit quality number for diff2 spectrum relative amplitude of the residual compared to the standard deveiation of the noise';
                MRSCont.QM.tables.Properties.VariableUnits{'relResdiff2'} = 'arbitrary';
        end
    end

    %Output as .tsv
    osp_WriteBIDsTable(MRSCont.QM.tables, [outputFolder filesep 'QM_processed_spectra'])
end

%% Clean up and save
% Set exit flags and version
MRSCont.flags.didFit           = 1;

diary off
% Save the output structure to the output folder
% Determine output folder
outputFolder    = MRSCont.outputFolder;
outputFile      = MRSCont.outputFile;
if ~exist(outputFolder,'dir')
    mkdir(outputFolder);
end

% Optional:  Create all pdf figures
if MRSCont.opts.savePDF
    osp_plotAllPDF(MRSCont, 'OspreyFit');
end

if MRSCont.flags.isGUI
    MRSCont.flags.isGUI = 0;
    save(fullfile(outputFolder, outputFile), 'MRSCont','-v7.3');
    MRSCont.flags.isGUI = 1;
else
   save(fullfile(outputFolder, outputFile), 'MRSCont','-v7.3');
end

end
function [MRSCont] = OspreyQuantify(MRSCont)
%% [MRSCont] = OspreyQuantify(MRSCont)
%   This function transforms the raw amplitude parameters determined during
%   OspreyFit into quantitative estimates of metabolite levels.
%
%   By default, OspreyQuantify will report tCr ratios for all metabolites.
%   These values will not undergo any further correction for tissue
%   content, or relaxation.
%
%   If some sort of unsuppressed data has been provided, OspreyQuantify will
%   calculate concentration estimates in institutional units. These values
%   will have varying degrees of corrections and assumptions.
%
%   USAGE:
%       MRSCont = OspreyQuantify(MRSCont);
%
%   INPUTS:
%       MRSCont     = Osprey MRS data container.
%
%   OUTPUTS:
%       MRSCont     = Osprey MRS data container.
%
%   AUTHOR:
%       Dr. Georg Oeltzschner (Johns Hopkins University, 2019-10-09)
%       goeltzs1@jhmi.edu
%
%   CREDITS:
%       This code is based on numerous functions from the FID-A toolbox by
%       Dr. Jamie Near (McGill University)
%       https://github.com/CIC-methods/FID-A
%       Simpson et al., Magn Reson Med 77:23-33 (2017)
%
%   HISTORY:
%       2019-10-09: First version of the code.
%       2019-10-22: HZ added tables.

outputFolder = MRSCont.outputFolder;
diary(fullfile(outputFolder, 'LogFile.txt'));

% Checking for version, toolbox, and previously run modules
[~,MRSCont.ver.CheckOsp ] = osp_CheckRunPreviousModule(MRSCont, 'OspreyQuantify');


%%% 0. CHECK WHICH QUANTIFICATIONS CAN BE DONE %%%
% tCr ratios can always be calculated (unless the unlikely case that Cr is
% not in the basis set, a case we'll omit for now).
qtfyCr = 1;

% Check which types of metabolite data are available
SubSpectraFitted =size(MRSCont.fit.results.metab.fitParams,3);
BasisSetsFitted =size(MRSCont.fit.results.metab.fitParams,1);


% Check which types of water data are available
if [MRSCont.flags.hasRef MRSCont.flags.hasWater] == [1 1]
        % If both water reference and short-TE water data have been
        % provided, use the one with shorter echo time.
        qtfyH2O     = 1;
        waterType   = 'w';
elseif [MRSCont.flags.hasRef MRSCont.flags.hasWater] == [1 0]
        % If only one type of water data has been provided, use it.
        qtfyH2O     = 1;
        waterType   = 'ref';
elseif [MRSCont.flags.hasRef MRSCont.flags.hasWater] == [0 1]
        % If only one type of water data has been provided, use it.
        qtfyH2O     = 1;
        waterType   = 'w';
elseif [MRSCont.flags.hasRef MRSCont.flags.hasWater] == [0 0]
        % If no water ref has been provided, only tCr ratios can be
        % provided.
        qtfyH2O     = 0;
end

% Get the fieldstrength for proper relaxation correction
if qtfyH2O
    Bo = MRSCont.raw{1}.Bo;
    if (Bo >= 2.8 && Bo < 3.1)
            Bo = '3T';
    else
            Bo = '7T';
    end
end
% Check whether segmentation has been run, and whether tissue parameters
% exist. In that case, we can do CSF correction, and full tissue
% correction.
if qtfyH2O == 1 && MRSCont.flags.didSeg && isfield(MRSCont.seg, 'tissue')
    qtfyCSF     = 1;
    qtfyTiss    = 1;
else
    qtfyCSF     = 0;
    qtfyTiss    = 0;
end

% Check whether tissue correction is available and whether GABA-edited
% MEGA-PRESS has been run. In this case, we can apply the alpha correction
% (Harris et al, J Magn Reson Imaging 42:1431-40 (2015)).
if qtfyTiss == 1 && MRSCont.flags.isMEGA && (strcmp(MRSCont.opts.editTarget{1},'GABA'))
    qtfyAlpha   = 1;
else if qtfyTiss == 1 && (MRSCont.flags.isHERMES || MRSCont.flags.isHERCULES) && (strcmp(MRSCont.opts.editTarget{1},'GABA') || strcmp(MRSCont.opts.editTarget{2},'GABA'))
    qtfyAlpha   = 1;
     else
        qtfyAlpha   = 0;
    end
end

warning('off','all');

% Set up saving location
saveDestination = fullfile(MRSCont.outputFolder, 'QuantifyResults');
if ~exist(saveDestination,'dir')
    mkdir(saveDestination);
end


% Add combinations of metabolites to the basisset
for ss = 1 : SubSpectraFitted
    if ~strcmp(MRSCont.opts.fit.method, 'LCModel')
        for mm = 1 : BasisSetsFitted
            if ~isempty(MRSCont.fit.resBasisSet.metab.(MRSCont.info.metab.unique_ndatapoint_spectralwidth{1}){mm,1,ss})
                if ~iscell(MRSCont.fit.results) %Is SVS
                    MRSCont.quantify.names.metab{mm,ss} = MRSCont.fit.resBasisSet.metab.(MRSCont.info.metab.unique_ndatapoint_spectralwidth{1}){mm,1,ss}.name;
                    MRSCont.quantify.names.SubSpectra{mm,ss} = MRSCont.fit.resBasisSet.metab.(MRSCont.info.metab.unique_ndatapoint_spectralwidth{1}){mm,1,ss}.names{1};
                else %Is DualVoxel
                   MRSCont.quantify.names.metab{mm,ss} = MRSCont.fit.resBasisSet{1,1}.metab.(MRSCont.info.metab.unique_ndatapoint_spectralwidth{1}){mm,1,ss}.name;
                   MRSCont.quantify.names.SubSpectra{mm,ss} = MRSCont.fit.resBasisSet{1,1}.metab.(MRSCont.info.metab.unique_ndatapoint_spectralwidth{1}){mm,1,ss}.names{1};
                end
            end
        end
    else
        MRSCont.quantify.names.metab{1,1} = MRSCont.fit.results.metab.fitParams{1, 1}.name;
        MRSCont.quantify.names.SubSpectra{1,1} = MRSCont.processed.metab{1, 1}.names{1};
    end
end

for ss = 1 : SubSpectraFitted
    for kk = 1:MRSCont.nDatasets(1)
        for mm = 1 : BasisSetsFitted
            if ~isempty(MRSCont.quantify.names.metab{mm,ss})
                if  ~iscell(MRSCont.fit.results) %Is SVS %Is SVS
                    MRSCont.quantify.amplMets{mm,kk,ss}.metab = MRSCont.fit.results.metab.fitParams{mm,kk,ss}.ampl;
                else %Is DualVoxel
                   MRSCont.quantify.amplMets{mm,kk,ss}.metab(:,1) = MRSCont.fit.results{1}.metab.fitParams{mm,kk,ss}.ampl;
                   MRSCont.quantify.amplMets{mm,kk,ss}.metab(:,2) = MRSCont.fit.results{2}.metab.fitParams{mm,kk,ss}.ampl;
                end
            end
        end
    end
end

if strcmp(MRSCont.opts.fit.method, 'LCModel')
    for kk = 1:MRSCont.nDatasets(1)
        if  ~iscell(MRSCont.fit.results) %Is SVS %Is SVS
            MRSCont.quantify.CRLB{kk}.metab = MRSCont.fit.results.metab.fitParams{kk}.CRLB';
            MRSCont.quantify.h2oarea{kk}.metab = MRSCont.fit.results.metab.fitParams{kk}.h2oarea;
        else %Is DualVoxel
            MRSCont.quantify.CRLB{kk}.metab(:,1) = MRSCont.fit.results{1}.metab.fitParams{kk}.CRLB';
           MRSCont.quantify.CRLB{kk}.metab(:,2) = MRSCont.fit.results{2}.metab.fitParams{kk}.CRLB';
           MRSCont.quantify.h2oarea{kk}.metab(:,1) = MRSCont.fit.results{1}.metab.fitParams{kk}.h2oarea;
           MRSCont.quantify.h2oarea{kk}.metab(:,2) = MRSCont.fit.results{2}.metab.fitParams{kk}.h2oarea;
        end
    end
end

MRSCont = addMetabComb(MRSCont);


%% Loop over all datasets
QuantifyTime = tic;
if MRSCont.flags.isGUI && isfield(MRSCont.flags,'inProgress')
    progressText = MRSCont.flags.inProgress;
else
    progressText = '';
end
fprintf('\n');
if MRSCont.flags.isGUI && isfield(MRSCont.flags,'inProgress')
    progressText = MRSCont.flags.inProgress;
end
for kk = 1:MRSCont.nDatasets(1)
    [~] = printLog('OspreyQuant',kk,1,MRSCont.nDatasets,progressText,MRSCont.flags.isGUI ,MRSCont.flags.isMRSI);

    %%% 1. GET BASIS SET AND FIT AMPLITUDES %%%
    metsName = MRSCont.quantify.names; % just for the names
    amplMets = MRSCont.quantify.amplMets(:,kk,:);


    %%% 2. GET CREATINE RATIOS %%%
    % We can always do this, but let's use the flag just to be safe:
    if qtfyCr

        % Extract metabolite amplitudes from fit
        tCrRatios = quantCr(metsName, amplMets);

        % Save back to Osprey data container
        for ss = 1 :SubSpectraFitted
            for mm = 1 :BasisSetsFitted
                if ~isempty( tCrRatios{mm,ss})
                    MRSCont.quantify.metab.tCr{mm,kk,ss}  = tCrRatios{mm,ss}.metab;
                end
            end
        end

    end


    %%% 3. GET WATER-SCALED, TISSUE-UNCORRECTED RATIOS %%%
    if qtfyH2O
        if ~strcmp(MRSCont.opts.fit.method, 'LCModel')
            if  ~iscell(MRSCont.fit.results) %Is SVS %Is SVS
                amplWater = MRSCont.fit.results.(waterType).fitParams{kk}.ampl;
            else %Is DualVoxel
               amplWater(:,1) = MRSCont.fit.results{1}.(waterType).fitParams{kk}.ampl;
               amplWater(:,2) = MRSCont.fit.results{2}.(waterType).fitParams{kk}.ampl;
            end
        else
            % Get WCONC, ATTMET, and ATTH2O from control file
            LCMparam = osp_readlcm_control(MRSCont.opts.fit.lcmodel.controlfileA{kk});
            if isfield(LCMparam, 'WCONC') % User-supplied WCONC
                amplWater = str2double(LCMparam.WCONC);
            else
                amplWater = 35880; %LCModel default WCONC assumes pure WM
            end

            if isfield(LCMparam, 'ATTMET') % User-supplied ATTMET
                amplWater = amplWater * str2double(LCMparam.ATTMET);
            else
                 %Do nothing as LCModel default ATTMET is 1
            end

            if isfield(LCMparam, 'ATTH2O') % User-supplied ATTH2O
                amplWater = amplWater / str2double(LCMparam.ATTH2O);
            else
                amplWater = amplWater / 0.7; %LCModel default ATTH2O is 0.7
            end
        end

        % Get repetition times
        metsTR  = MRSCont.processed.metab{kk}.tr * 1e-3;
        waterTR = MRSCont.processed.(waterType){kk}.tr * 1e-3;
        % Get echo times
        metsTE  = MRSCont.processed.metab{kk}.te * 1e-3;
        waterTE = MRSCont.processed.(waterType){kk}.te * 1e-3;
        % Calculate water-scaled, but not tissue-corrected metabolite levels
        rawWaterScaled = quantH2O(metsName, amplMets, amplWater, metsTR, waterTR, metsTE, waterTE,Bo);

        % Save back to Osprey data container
        for ss = 1 :SubSpectraFitted
            for mm = 1 :BasisSetsFitted
                if ~isempty( rawWaterScaled{mm,ss})
                    MRSCont.quantify.metab.rawWaterScaled{mm,kk,ss} = rawWaterScaled{mm,ss}.metab;
                end
            end
        end

    end


    %%% 4. GET CSF CORRECTION %%%
    if qtfyCSF

        % Apply CSF correction
        fCSF = MRSCont.seg.tissue.fCSF(kk,:);
        CSFWaterScaled = quantCSF(rawWaterScaled, fCSF,SubSpectraFitted);

        % Save back to Osprey data container
        for ss = 1 :SubSpectraFitted
            for mm = 1 :BasisSetsFitted
                if ~isempty( CSFWaterScaled{mm,ss})
                    MRSCont.quantify.metab.CSFWaterScaled{mm,kk,ss} = CSFWaterScaled{mm,ss}.metab;
                end
            end
        end
    end


    %%% 5. GET TISSUE CORRECTION %%%
    if qtfyTiss

        % Apply tissue correction
        fGM = MRSCont.seg.tissue.fGM(kk,:);
        fWM = MRSCont.seg.tissue.fWM(kk,:);
function [MRSCont] = RunOspreyJob(jobFilePath)
%% [MRSCont] = RunOspreyJob(jobFilePath)
%   This function creates performs a full Osprey analysis on the supplied 
%   job file. This is the foundation for the compiled version of Osprey.
%
%   USAGE:
%       MRSCont = RunOspreyJob(jobFilePath)
%
%   INPUTS:
%       jobFilePath     = path to the Osprey jobfile (.m, .csv or .jason).
%
%   OUTPUTS:
%       MRSCont     = Osprey MRS data container.
%
%   AUTHOR:
%       Dr. Helge Zoellner (Johns Hopkins University, 2022-05-17)
%       hzoelln2@jhmi.edu
%
%   CREDITS:
%       This code is based on numerous functions from the FID-A toolbox by
%       Dr. Jamie Near (McGill University)
%       https://github.com/CIC-methods/FID-A
%       Simpson et al., Magn Reson Med 77:23-33 (2017)
%
%   HISTORY:
%       2022-05-17: First version of the code.

    MRSCont = OspreyJob(jobFilePath,0,'11');

    MRSCont = OspreyLoad(MRSCont);

    MRSCont = OspreyProcess(MRSCont);

    MRSCont = OspreyFit(MRSCont);

    if ~isempty(MRSCont.files_nii)
        MRSCont = OspreyCoreg(MRSCont);
        if ~isempty(MRSCont.files_seg)
            seg = [num2str(~isempty(MRSCont.files_seg)) num2str(exist(MRSCont.files_seg{1}{1},'file'))];
        else
            seg = '00';
        end
        switch seg
            case '00' %Do normal segmentation (No files_seg)
                MRSCont = OspreySeg(MRSCont);
            case '11' %files_seg are defined and finished.
                MRSCont = OspreySeg(MRSCont);
            otherwise % (10) files_seg are defined, but not finished yet. (Do nothing)
        end

    end

    MRSCont = OspreyQuantify(MRSCont);

    MRSCont = OspreyOverview(MRSCont);

    for kk = 1 : MRSCont.nDatasets
        [MRSCont] = OspreyHTMLReport(MRSCont,kk);
    end

end

