function [MRSCont] = osp_fitHERMES(MRSCont)
%% [MRSCont] = osp_fitHERMES(MRSCont)
%   This function performs spectral fitting of HERMES MRS data.
%
%   USAGE:
%       [MRSCont] = osp_fitHERMES(MRSCont);
%
%   INPUTS:
%       MRSCont     = Osprey MRS data container.
%
%   OUTPUTS:
%       MRSCont     = Osprey MRS data container.
%
%   AUTHOR:
%       Dr. Georg Oeltzschner (Johns Hopkins University, 2019-04-12)
%       goeltzs1@jhmi.edu
%
%   CREDITS:
%       This code is based on numerous functions from the FID-A toolbox by
%       Dr. Jamie Near (McGill University)
%       https://github.com/CIC-methods/FID-A
%       Simpson et al., Magn Reson Med 77:23-33 (2017)
%
%   HISTORY:
%       2019-04-12: First version of the code.


% Loop over all the datasets here
metFitTime = tic;
if MRSCont.flags.isGUI
    progressText = MRSCont.flags.inProgress;
else
    progressText = '';
end
for kk = 1:MRSCont.nDatasets
    [~] = printLog('OspreyFit',kk,1,MRSCont.nDatasets,progressText,MRSCont.flags.isGUI ,MRSCont.flags.isMRSI); 
    %%% 1. DETERMINE THE FITTING STYLE %%%
    % Extract fit options
    fitOpts     = MRSCont.opts.fit;
    fitModel    = fitOpts.method;
    fitStyle    = fitOpts.style;


    %%% 2. SEPARATE FIT %%%
    % For the separate (classic) HERMES fit, model the two DIFF
    % spectra and the SUM spectrum separately.
    if strcmp(fitStyle, 'Separate')
        if ~(MRSCont.flags.didFit == 1 && MRSCont.flags.speedUp && isfield(MRSCont, 'fit') && (kk > size(MRSCont.fit.results.metab.fitParams,2))) || ~strcmp(MRSCont.ver.Osp,MRSCont.ver.CheckOsp)  

            %%% 2a. FIT SUM-SPECTRUM
            % Apply scaling factor to the data
            dataToFit   = op_takesubspec(MRSCont.processed.metab{kk},'sum');
            basisSetSum = MRSCont.fit.basisSet;
            basisSetSum.fids = basisSetSum.fids(:,:,7);
            basisSetSum.specs = basisSetSum.specs(:,:,7);
            dataToFit   = op_ampScale(dataToFit, 1/MRSCont.fit.scale{kk});

            fitOpts.GAP = MRSCont.opts.fit.GAP.sum;
            % Call the fit function
            [fitParamsSum, resBasisSetSum] = fit_runFit(dataToFit, basisSetSum, fitModel, fitOpts);

            % Save back the basis set and fit parameters to MRSCont
            MRSCont.fit.resBasisSet.metab{1,kk,1}             = resBasisSetSum;
            MRSCont.fit.results.metab.fitParams{1,kk,1}   = fitParamsSum;


            %%% 2b. FIT DIFF1-SPECTRUM
            % Apply scaling factor to the data
            dataToFit   = op_takesubspec(MRSCont.processed.metab{kk},'diff1');
            basisSetDiff1 = MRSCont.fit.basisSet;
            basisSetDiff1.fids = basisSetDiff1.fids(:,:,5);
            basisSetDiff1.specs = basisSetDiff1.specs(:,:,5);
            dataToFit   = op_ampScale(dataToFit, 1/MRSCont.fit.scale{kk});
            dataToFit.refShift   = fitParamsSum.refShift;
            dataToFit.refFWHM   = fitParamsSum.refFWHM;

            if isfield(fitOpts, 'coMM3') && ~strcmp(fitOpts.coMM3, 'none')
                [basisSetDiff1] = osp_addDiffMMPeaks(basisSetDiff1,basisSetSum,fitOpts);
            end

            fitOpts.GAP = MRSCont.opts.fit.GAP.diff1;
            % Call the fit function
            [fitParamsDiff1, resBasisSetDiff1]  = fit_runFit(dataToFit, basisSetDiff1, fitModel, fitOpts);

            % Save back the basis set and fit parameters to MRSCont
            MRSCont.fit.resBasisSet.metab{1,kk,2}           = resBasisSetDiff1;
            MRSCont.fit.results.metab.fitParams{1,kk,2} = fitParamsDiff1;


            %%% 2c. FIT DIFF2-SPECTRUM
            % Apply scaling factor to the data
            dataToFit   = op_takesubspec(MRSCont.processed.metab{kk},'diff2');
            basisSetDiff2 = MRSCont.fit.basisSet;
            basisSetDiff2.fids = basisSetDiff2.fids(:,:,6);
            basisSetDiff2.specs = basisSetDiff2.specs(:,:,6);
            dataToFit   = op_ampScale(dataToFit, 1/MRSCont.fit.scale{kk});
            dataToFit.refShift   = fitParamsSum.refShift;
            dataToFit.refFWHM   = fitParamsSum.refFWHM;
            fitOpts.Diff2 = 1;

            fitOpts.GAP = MRSCont.opts.fit.GAP.diff2;
            % Call the fit function
            [fitParamsDiff2, resBasisSetDiff2]  = fit_runFit(dataToFit, basisSetDiff2, fitModel, fitOpts);

            % Save back the basis set and fit parameters to MRSCont
            MRSCont.fit.resBasisSet.metab{1,kk,3}           = resBasisSetDiff2;
            MRSCont.fit.results.metab.fitParams{1,kk,3} = fitParamsDiff2;
        end
    end


    %%% 3. CONCATENATED FIT %%%
    % For the concatenated MEGA fit, model the DIFF1 and SUM spectra
    % together.
    if strcmp(fitStyle, 'Concatenated')
        if ~(MRSCont.flags.didFit == 1 && MRSCont.flags.speedUp && isfield(MRSCont, 'fit') && (kk > length(MRSCont.fit.results.conc.fitParams))) || ~strcmp(MRSCont.ver.Osp,MRSCont.ver.CheckOsp)   

            %%% 3a. FIT CONCATENATED SPECTRUM
            % Apply scaling factor to the data
            dataToFit   = {op_takesubspec(MRSCont.processed.metab{kk},7), op_takesubspec(MRSCont.processed.metab{kk},5), op_takesubspec(MRSCont.processed.metab{kk},6)};
            basisSetConc = MRSCont.fit.basisSet;
            basisSetConc.fids = basisSetConc.fids(:,:,5:7);
            basisSetConc.specs = basisSetConc.specs(:,:,5:7);
            for rr = 1:length(dataToFit)
                dataToFit{rr}   = op_ampScale(dataToFit{rr}, 1/MRSCont.fit.scale{kk});
            end

            % Call the fit function
            [fitParamsConc, resBasisSetConc] = fit_runFitMultiplex(dataToFit, basisSetConc, fitModel, fitOpts);

            % Save back the basis set and fit parameters to MRSCont
            MRSCont.fit.resBasisSet.conc{kk}           = resBasisSetConc;
            MRSCont.fit.results.conc.fitParams{kk} = fitParamsConc;
        end
    end
end
time = toc(metFitTime);
[~] = printLog('done',time,1,MRSCont.nDatasets,progressText,MRSCont.flags.isGUI ,MRSCont.flags.isMRSI);
MRSCont.runtime.FitMet = time;

end

function [BASISdiff] = osp_addDiffMMPeaks(BASISdiff,BASISoff,fitOpts)
    n = BASISdiff.n;
    sw = BASISdiff.spectralwidth;
    Bo = BASISdiff.Bo;
    centerFreq = BASISdiff.centerFreq;
    % The amplitude and FWHM values are determined as for the LCModel and
    % TARQUIN algorithms (see Wilson et al., MRM 2011).
    hzppm = Bo*42.577;

    % To scale the amplitudes correctly, we first need to determine the
    % area of the 3.027 ppm CH3 signal of creatine
    [CrArea] = detCrArea(BASISoff);
    oneProtonArea = CrArea/3;

    % Next, we determine the area of a Gaussian singlet with nominal area 1
    testGaussian    = op_gaussianPeak(n,sw,Bo,centerFreq,0.1*hzppm,0,1);
    testGaussian    = op_dccorr(testGaussian,'p');
    gaussianArea    = sum(real(testGaussian.specs));

     % Find the GABA basis function
    idx_GABA          = find(strcmp(BASISdiff.name,'GABA'));
    if isempty(idx_GABA)
        error('No basis function with nametag ''GABA'' found! Abort!');
    end

    if strcmp(fitOpts.coMM3, '1to1GABA') % 1:1 GABA and co-edited MM3 model
        MM3co  = op_gaussianPeak(n,sw,Bo,centerFreq,fitOpts.FWHMcoMM3,3,2*oneProtonArea/gaussianArea);
        MM3co  = op_dccorr(MM3co,'p');
        BASISdiff.fids(:,idx_GABA)  = BASISdiff.fids(:,idx_GABA) +  MM3co.fids;
        BASISdiff.specs(:,idx_GABA) = BASISdiff.specs(:,idx_GABA) +  MM3co.specs;
    end    

    if strcmp(fitOpts.coMM3, '3to2MM') % 3:2 MM09 and co-edited MM3 model
        idx_MM          = find(strcmp(BASISdiff.name,'MM09'));
        if isempty(idx_MM)
            error('No basis function with nametag ''MM09'' found! Abort!');
        end
        MM3co  = op_gaussianPeak(n,sw,Bo,centerFreq,fitOpts.FWHMcoMM3,3,2*oneProtonArea/gaussianArea);
        MM3co  = op_dccorr(MM3co,'p');
        BASISdiff.fids(:,idx_MM)  = BASISdiff.fids(:,idx_MM) +  MM3co.fids;
        BASISdiff.specs(:,idx_MM) = BASISdiff.specs(:,idx_MM) +  MM3co.specs;
    end   

    if strcmp(fitOpts.coMM3, '3to2MMsoft') % 3:2 MM09 and co-edited MM3 model
        idx_MM          = find(strcmp(BASISdiff.name,'MM09'));
        if isempty(idx_MM)
            error('No basis function with nametag ''MM09'' found! Abort!');
        end
        MM3co  = op_gaussianPeak(n,sw,Bo,centerFreq,fitOpts.FWHMcoMM3,3,2*oneProtonArea/gaussianArea);
        MM3co  = op_dccorr(MM3co,'p');
        BASISdiff.name{BASISdiff.nMets+BASISdiff.nMM+1}       = 'MM3co';
        BASISdiff.fids(:,BASISdiff.nMets+BASISdiff.nMM+1)   = MM3co.fids;
        BASISdiff.specs(:,BASISdiff.nMets+BASISdiff.nMM+1)  = MM3co.specs;    
        BASISdiff.nMM = BASISdiff.nMM + 1;
    end 

    if strcmp(fitOpts.coMM3, 'freeGauss') || strcmp(fitOpts.coMM3, 'fixedGauss') || strcmp(fitOpts.coMM3, '1to1GABAsoft')...
        || strcmp(fitOpts.coMM3, '2to3GABAsoft') || strcmp(fitOpts.coMM3, '3to2GABAsoft')% free co-edited MM3 model and soft constraints model
        MM3co  = op_gaussianPeak(n,sw,Bo,centerFreq,fitOpts.FWHMcoMM3,3,2*oneProtonArea/gaussianArea);
        MM3co  = op_dccorr(MM3co,'p');
        BASISdiff.name{BASISdiff.nMets+BASISdiff.nMM+1}       = 'MM3co';
        BASISdiff.fids(:,BASISdiff.nMets+BASISdiff.nMM+1)   = MM3co.fids;
        BASISdiff.specs(:,BASISdiff.nMets+BASISdiff.nMM+1)  = MM3co.specs;    
        BASISdiff.nMM = BASISdiff.nMM + 1;
    end

    if strcmp(fitOpts.coMM3, 'freeGauss')
        BASISdiff.coMM3.MMArea = 2*oneProtonArea/gaussianArea;
        BASISdiff.coMM3.n = n;
        BASISdiff.coMM3.sw = sw;
        BASISdiff.coMM3.Bo = Bo;
        BASISdiff.coMM3.centerFreq = centerFreq;        
    end

end

% detCrArea.m
% Georg Oeltzschner, Johns Hopkins University 2020
% 
% USAGE:
% [CrArea] = detCrArea(buffer);
% 
% DESCRIPTION:
% Finds the creatine spectrum in the temporary basis set buffer, then fits
% a Lorentzian to the 3.027 ppm CH3 creatine singlet to determine its area.
% Subsequently, macromolecule and lipid basis functions are scaled
% accordingly.
% 
% INPUTS:
% in        = a temporary buffer containing simulated basis functions
%
% OUTPUTS:
% CrArea    = Estimated area under the 3.027 ppm CH3 Cr singlet.


function [CrArea] = detCrArea(in);

% Find the creatine basis function
idx_Cr          = find(strcmp(in.name,'Cr'));
if isempty(idx_Cr)
    error('No basis function with nametag ''Cr'' found! Abort!');
end

%[~, idx_3027]   = min(abs(buffer.ppm(:,1)-3.027));

% Determine the window where we are going to look for the peak.
ppm = in.ppm(1,:);
ppmmin = 3.027 - 0.4;
ppmmax = 3.027 + 0.4;
refWindow = in.specs(ppm>ppmmin & ppm<ppmmax, idx_Cr);
ppmWindow = in.ppm(ppm>ppmmin & ppm<ppmmax);

% Find the maximum and its index
maxRef_index    = find(abs(real(refWindow)) == max(abs(real((refWindow)))));
maxRef          = real(refWindow(maxRef_index));

% Determine an initial estimate for the FWHM
% Peak lines can be super narrow, so overestimate it slightly
gtHalfMax   = find(abs(real(refWindow)) >= 0.4*abs(maxRef));
FWHM1       = abs(ppmWindow(gtHalfMax(1)) - ppmWindow(gtHalfMax(end)));
FWHM1       = FWHM1*(42.577*in.Bo(1));  %Assumes proton.

% Determine an initial estimate for the center frequency of the Cr peak
crFreq = ppmWindow(maxRef_index);

% Set up the fit
parsGuess=zeros(1,5);
parsGuess(1) = maxRef;  % amplitude
parsGuess(2) = (5*in.Bo/3)/(42.577*in.Bo); %FWHM.  Assumes Proton.  LW = 5/3 Hz/T.   % FWHM. Assumes Proton.
parsGuess(3) = crFreq;  % center frequency
parsGuess(4) = 0;       % baseline offset
parsGuess(5) = 0;       % phase

% Run first guess
yGuess  = op_lorentz(parsGuess, ppmWindow);
parsFit = nlinfit(ppmWindow, real(refWindow'), @op_lorentz, parsGuess);
yFit    = op_lorentz(parsFit, ppmWindow);

% figure;
% plot(ppmWindow,refWindow,'.',ppmWindow,yGuess,':',ppmWindow,yFit);
% legend('data','guess','fit');

CrArea = sum(yFit);

